import { Source } from './source';
import { mapEvent } from './mapper';
export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}
  async *stream(): AsyncGenerator<string> {
    const lease = await this.source.open();
    let failed = false;
    try {
      for (;;) {
        const value = await lease.read();
        if (value === null) break;
        yield this.mapper(value);
      }
    } catch (error) {
      failed = true;
      throw error;
    } finally {
      try {
        await lease.close();
      } catch (closeError) {
        if (!failed) throw closeError;
      }
    }
  }
}
EOF
cat > checks/lease.cjs <<'EOF'
const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');
function make(values, o = {}) {
  const s = { opens: 0, closes: 0, reads: 0 };
  const source = { open: async () => { s.opens++; return {
    read: async () => { s.reads++; if (o.readFail && s.reads === o.readFail) throw new Error('read'); return values.length ? values.shift() : null; },
    close: async () => { s.closes++; if (o.closeFail) throw new Error('close'); } }; } };
  return { s, svc: new EventService(source, o.mapper) };
}
async function main() {
  // unopened generator
  let m = make(['a']); m.svc.stream(); await m.svc.stream().return(); assert.deepEqual(m.s, { opens: 0, closes: 0, reads: 0 });
  // no read ahead, break closes once
  m = make(['a', 'b', 'c']);
  for await (const v of m.svc.stream()) { assert.equal(v, 'A'); break; }
  assert.deepEqual(m.s, { opens: 1, closes: 1, reads: 1 });
  // exhaustion
  m = make(['a']); const out = []; for await (const v of m.svc.stream()) out.push(v);
  assert.deepEqual(out, ['A']); assert.deepEqual(m.s, { opens: 1, closes: 1, reads: 2 });
  // read failure, with and without close failure
  m = make(['a'], { readFail: 1 }); await assert.rejects(m.svc.stream().next(), /read/); assert.equal(m.s.closes, 1);
  m = make(['a'], { readFail: 1, closeFail: true }); await assert.rejects(m.svc.stream().next(), /read/); assert.equal(m.s.closes, 1);
  // mapper failure
  const bad = () => { throw new Error('map'); };
  m = make(['a'], { mapper: bad }); await assert.rejects(m.svc.stream().next(), /map/); assert.equal(m.s.closes, 1);
  m = make(['a'], { mapper: bad, closeFail: true }); await assert.rejects(m.svc.stream().next(), /map/); assert.equal(m.s.closes, 1);
  // injected throw
  m = make(['a', 'b']); let g = m.svc.stream(); await g.next();
  await assert.rejects(g.throw(new Error('inj')), /inj/); assert.equal(m.s.closes, 1);
  m = make(['a', 'b'], { closeFail: true }); g = m.svc.stream(); await g.next();
  await assert.rejects(g.throw(new Error('inj')), /inj/); assert.equal(m.s.closes, 1);
  // close failure alone propagates
  m = make(['a'], { closeFail: true }); await assert.rejects((async () => { for await (const _ of m.svc.stream()); })(), /close/);
  m = make(['a', 'b'], { closeFail: true }); g = m.svc.stream(); await g.next(); await assert.rejects(g.return(), /close/); assert.equal(m.s.closes, 1);
}
module.exports = main();
EOF
